update public.ppg_lessons set body_th = 'โปรแกรมนำเสนอที่ใช้บ่อยคือ PowerPoint, Google Slides, LibreOffice Impress, Keynote และ Canva ทุกโปรแกรมทำงานคล้ายกัน หน้าต่าง PowerPoint มีริบบอนด้านบน บานสไลด์ด้านซ้าย พื้นที่แก้ไขกึ่งกลาง และบานบันทึกด้านล่าง มุมมองที่ใช้บ่อยคือ Normal, Slide Sorter, Notes Page และ Slide Show' where lesson_key = 'chapter-03-lesson-01';
update public.ppg_lessons set title_th = 'เค้าโครงสไลด์ เพลซโฮลเดอร์ และการสร้างงานนำเสนอ' where lesson_key = 'chapter-03-lesson-02';
update public.ppg_lessons set what_learn_th = 'เลือกเค้าโครงสไลด์และเพลซโฮลเดอร์ให้พอดีกับเนื้อหา และสร้างงานนำเสนอได้' where lesson_key = 'chapter-03-lesson-02';
update public.ppg_lessons set why_th = 'เค้าโครงสไลด์ที่เหมาะสมช่วยให้จัดวางเนื้อหาได้เร็วและอ่านง่าย' where lesson_key = 'chapter-03-lesson-02';
update public.ppg_lessons set why_th = 'แก้ไขที่ต้นแบบครั้งเดียว ทุกสไลด์เปลี่ยนตาม' where lesson_key = 'chapter-03-lesson-03';
update public.ppg_lessons set body_th = 'สไลด์ต้นแบบคือสไลด์แม่ที่ควบคุมแบบอักษร สี ตำแหน่งเพลซโฮลเดอร์ และโลโก้ของทุกสไลด์ เทมเพลตคือชุดต้นแบบพร้อมนำไปใช้ทันที ทั้งสองช่วยทำให้การนำเสนอมีเอกลักษณ์เดียวกันและประหยัดเวลา' where lesson_key = 'chapter-03-lesson-03';
update public.ppg_lessons set what_next_th = 'ต่อไป: ภารกิจความรู้และข้อสอบหลังเรียน' where lesson_key = 'chapter-03-lesson-03';
update public.ppg_lesson_steps set body_th = 'เมื่อจบบทเรียนนี้ คุณจะบอกโปรแกรมนำเสนอที่ใช้บ่อย องค์ประกอบของหน้าต่าง และมุมมองหลักได้' where lesson_key = 'chapter-03-lesson-01' and order_index = 1;
update public.ppg_lesson_steps set body_th = 'โปรแกรมนำเสนอทุกโปรแกรมมีหลักการเดียวกัน คือวางข้อความและภาพบนสไลด์ จากนั้นนำเสนอทีละหน้า' where lesson_key = 'chapter-03-lesson-01' and order_index = 2;
update public.ppg_lesson_steps set body_th = 'ตัวอย่างงานขาย: ทีมขายเปิดข้อเสนอใน PowerPoint ส่วนทีมออกแบบใช้ Canva ทำภาพเพราะทำงานร่วมกันได้ง่าย' where lesson_key = 'chapter-03-lesson-01' and order_index = 3;
update public.ppg_lesson_steps set body_th = 'หน้าต่าง PowerPoint มีริบบอนด้านบน บานสไลด์ด้านซ้าย พื้นที่แก้ไขกึ่งกลาง และบานบันทึกด้านล่าง ใช้มุมมองปกติเมื่อแก้ไขสไลด์ ใช้มุมมอง Slide Sorter เมื่อเรียงลำดับ และใช้มุมมอง Slide Show เมื่อนำเสนอจริง' where lesson_key = 'chapter-03-lesson-01' and order_index = 4;
update public.ppg_lesson_steps set check_prompt_th = 'เมื่อต้องการเรียงลำดับสไลด์ใหม่ควรใช้มุมมองใด' where lesson_key = 'chapter-03-lesson-01' and order_index = 5;
update public.ppg_lesson_steps set check_explanation_th = 'มุมมอง Slide Sorter แสดงสไลด์ทั้งหมดเป็นภาพเล็ก จึงลากสลับตำแหน่งได้ง่าย' where lesson_key = 'chapter-03-lesson-01' and order_index = 5;
update public.ppg_lesson_steps set body_th = 'รู้จักโปรแกรม หน้าต่าง และมุมมอง แล้วคุณจะเริ่มสร้างงานนำเสนอได้อย่างมั่นใจ' where lesson_key = 'chapter-03-lesson-01' and order_index = 6;
update public.ppg_lesson_steps set body_th = 'เมื่อจบบทเรียนนี้ คุณจะเลือกเค้าโครงสไลด์และเพลซโฮลเดอร์ให้พอดีกับเนื้อหา และสร้างงานนำเสนอได้' where lesson_key = 'chapter-03-lesson-02' and order_index = 1;
update public.ppg_lesson_steps set body_th = 'เพลซโฮลเดอร์บอกตำแหน่งของชื่อเรื่อง เนื้อหา และภาพล่วงหน้า คุณเพียงคลิกแล้วพิมพ์' where lesson_key = 'chapter-03-lesson-02' and order_index = 2;
update public.ppg_lesson_steps set body_th = 'ตัวอย่างสไลด์เปรียบเทียบคู่แข่ง ใช้เลย์เอาต์สองคอลัมน์เพื่อวางจุดแข็งและจุดอ่อนคู่กัน' where lesson_key = 'chapter-03-lesson-02' and order_index = 3;
update public.ppg_lesson_steps set body_th = 'เลือกเลย์เอาต์ให้พอดีกับเนื้อหา จากนั้นใช้เพลซโฮลเดอร์ช่วยจัดวางเร็วขึ้น' where lesson_key = 'chapter-03-lesson-02' and order_index = 6;
update public.ppg_lesson_steps set body_th = 'เมื่อจบบทเรียนนี้ คุณจะใช้สไลด์ต้นแบบและเทมเพลตทำให้ทั้งชุดมีรูปแบบเดียวกันได้' where lesson_key = 'chapter-03-lesson-03' and order_index = 1;
update public.ppg_lesson_steps set body_th = 'สไลด์ต้นแบบควบคุมแบบอักษร สี และตำแหน่งเพลซโฮลเดอร์ของทุกสไลด์ ถ้าแก้ไขที่ต้นแบบทุกสไลด์จะเปลี่ยนตาม' where lesson_key = 'chapter-03-lesson-03' and order_index = 2;
update public.ppg_lesson_steps set body_th = 'ตัวอย่าง: บริษัทมีโลโก้และสีตราสินค้า การตลาดจึงตั้งสไลด์ต้นแบบครั้งเดียว จากนั้นทุกข้อเสนอขายใช้รูปแบบเดียวกัน' where lesson_key = 'chapter-03-lesson-03' and order_index = 3;
update public.ppg_lesson_steps set body_th = 'ไปที่แท็บ View เลือก Slide Master แก้ไขแบบอักษรหรือตำแหน่ง จากนั้นเลือก Close Master View เมื่อเสร็จ แล้วค้นหาเทมเพลตจากไฟล์ > New หรือ Design > Themes' where lesson_key = 'chapter-03-lesson-03' and order_index = 4;
update public.ppg_lesson_steps set check_prompt_th = 'ถ้าต้องการทุกสไลด์ใช้แบบอักษรเดียวกัน ควรแก้ไขที่ไหน' where lesson_key = 'chapter-03-lesson-03' and order_index = 5;
update public.ppg_lesson_steps set check_explanation_th = 'สไลด์ต้นแบบคือแม่ของทุกสไลด์ แก้ไขครั้งเดียวจึงมีผลกับทั้งชุด' where lesson_key = 'chapter-03-lesson-03' and order_index = 5;
update public.ppg_lesson_steps set body_th = 'ตั้งต้นแบบให้ดีตั้งแต่แรก จากนั้นทั้งชุดจะมีรูปแบบเดียวกันโดยไม่ต้องแก้ซ้ำอีก' where lesson_key = 'chapter-03-lesson-03' and order_index = 6;
update public.ppg_knowledge_missions set instructions_th = 'ภารกิจความรู้: ตอบคำถามหกข้อเกี่ยวกับโปรแกรมนำเสนอ ผ่านเกณฑ์ 70% และทำซ้ำได้ไม่จำกัด' where module_key = 'chapter-03';
update public.ppg_knowledge_mission_questions set explanation_th = 'PowerPoint เป็นโปรแกรมนำเสนอ ส่วนโปรแกรมตารางและโปรแกรมตัดต่อวิดีโอทำงานต่างกัน' where module_key = 'chapter-03' and order_index = 1;
update public.ppg_knowledge_mission_questions set explanation_th = 'Google Slides, LibreOffice Impress, Keynote และ Canva เป็นโปรแกรมนำเสนอที่ทำงานคล้ายกับ PowerPoint' where module_key = 'chapter-03' and order_index = 2;
update public.ppg_chapter_test_questions set prompt_th = 'เมื่อต้องอ่านบันทึกผู้บรรยายขณะเตรียมควรใช้มุมมองใด' where chapter_key = 'chapter-03' and phase = 'post' and order_index = 5;
update public.ppg_chapter_test_questions set prompt_th = 'เพิ่ม New Slide ที่แท็บใด' where chapter_key = 'chapter-03' and phase = 'post' and order_index = 8;
update public.ppg_modules set summary_th = 'จัดการและตกแต่งสไลด์ การเน้นข้อความ สัญลักษณ์แสดงหัวข้อและการจัดลำดับเลข และการจัดวางข้อความกับกล่องข้อความ' where module_key = 'chapter-04';
update public.ppg_lessons set what_learn_th = 'เพิ่ม ทำซ้ำ ย้าย ซ่อน และตกแต่งสไลด์ให้พอดีกับลำดับเรื่อง' where lesson_key = 'chapter-04-lesson-01';
update public.ppg_lessons set body_th = 'การจัดการสไลด์หมายถึงการเพิ่ม ทำซ้ำ ย้าย ลบ และซ่อนสไลด์ตามลำดับเรื่อง การตกแต่งสไลด์คือการปรับพื้นหลังและสีให้อ่านง่ายและสอดคล้องกับเนื้อหา' where lesson_key = 'chapter-04-lesson-01';
update public.ppg_lessons set what_next_th = 'ต่อไป: เน้นข้อความ สัญลักษณ์แสดงหัวข้อ และการจัดลำดับเลข' where lesson_key = 'chapter-04-lesson-01';
update public.ppg_lessons set title_th = 'เน้นข้อความ สัญลักษณ์แสดงหัวข้อ และการจัดลำดับเลข' where lesson_key = 'chapter-04-lesson-02';
update public.ppg_lessons set what_learn_th = 'ใช้ตัวหนา ตัวเอียง สี และไฮไลต์อย่างพอดี และเลือกระหว่างสัญลักษณ์แสดงหัวข้อกับการจัดลำดับเลข' where lesson_key = 'chapter-04-lesson-02';
update public.ppg_lessons set body_th = 'การเน้นข้อความใช้เพื่อชี้จุดสำคัญ เช่น ตัวหนา ตัวเอียง ขีดเส้นใต้ สี และไฮไลต์ ควรเน้นเพียงหนึ่งหรือสองจุดต่อสไลด์ สัญลักษณ์แสดงหัวข้อเหมาะสมสำหรับรายการที่ลำดับไม่สำคัญ ส่วนการจัดลำดับเลขเหมาะสมสำหรับขั้นตอนที่ต้องเรียงตามลำดับ' where lesson_key = 'chapter-04-lesson-02';
update public.ppg_lessons set what_next_th = 'ต่อไป: จัดวางข้อความและย่อหน้า และกล่องข้อความ' where lesson_key = 'chapter-04-lesson-02';
update public.ppg_lessons set title_th = 'จัดวางข้อความและย่อหน้า และกล่องข้อความ' where lesson_key = 'chapter-04-lesson-03';
update public.ppg_lessons set what_learn_th = 'จัดข้อความ ตั้งระยะห่างบรรทัด และใช้กล่องข้อความให้อ่านง่าย' where lesson_key = 'chapter-04-lesson-03';
update public.ppg_lessons set body_th = 'การจัดวางข้อความหมายถึงการจัดข้อความชิดซ้าย ชิดขวา กึ่งกลาง หรือชิดขอบทั้งสองข้าง การตั้งระยะห่างบรรทัดและระยะห่างก่อนและหลังย่อหน้าช่วยให้อ่านสบาย กล่องข้อความใช้เมื่อต้องวางข้อความในตำแหน่งที่เค้าโครงไม่มี' where lesson_key = 'chapter-04-lesson-03';
update public.ppg_lesson_steps set body_th = 'ก่อนตกแต่ง จัดลำดับสไลด์ให้เรื่องต่อเนื่องก่อน เพราะลำดับสำคัญกว่าลูกเล่น' where lesson_key = 'chapter-04-lesson-01' and order_index = 2;
update public.ppg_lesson_steps set body_th = 'ตัวอย่างข้อเสนอการขายวางปัญหาของลูกค้าไว้ก่อนวิธีแก้ และซ่อนสไลด์ราคาไว้จนถึงช่วงท้าย' where lesson_key = 'chapter-04-lesson-01' and order_index = 3;
update public.ppg_lesson_steps set body_th = 'เพิ่มหรือทำซ้ำสไลด์ที่แท็บ Home ลากสไลด์ในมุมมอง Slide Sorter เพื่อย้ายลำดับ คลิกขวาแล้วเลือก Hide Slide เพื่อซ่อน และใช้แท็บ Design ตั้งพื้นหลังหรือธีม' where lesson_key = 'chapter-04-lesson-01' and order_index = 4;
update public.ppg_lesson_steps set check_explanation_th = 'การซ่อนสไลด์ยังเก็บเนื้อหาไว้ใช้ภายหลังโดยไม่แสดงเมื่อนำเสนอ' where lesson_key = 'chapter-04-lesson-01' and order_index = 5;
update public.ppg_lesson_steps set body_th = 'จัดลำดับเรื่องก่อน จากนั้นจึงตกแต่ง และซ่อนสไลด์ที่ยังไม่ใช้' where lesson_key = 'chapter-04-lesson-01' and order_index = 6;
update public.ppg_lesson_steps set body_th = 'การเน้นควรมีเหตุผล เช่น ชี้ตัวเลขที่ต้องตัดสินใจ ไม่ใช่เน้นทุกคำ' where lesson_key = 'chapter-04-lesson-02' and order_index = 2;
update public.ppg_lesson_steps set body_th = 'ตัวอย่างสไลด์รายงานความก้าวหน้าเน้นเฉพาะยอดขายที่ถึงเป้าเพียงจุดเดียว ส่วนที่เหลือใช้ข้อความปกติ' where lesson_key = 'chapter-04-lesson-02' and order_index = 3;
update public.ppg_lesson_steps set body_th = 'เลือกข้อความ จากนั้นใช้แท็บ Home คลิก Bold, Italic หรือ Underline เปลี่ยนสีที่ Font Color และเลือก Bullets หรือ Numbering ให้ตรงกับลักษณะรายการ' where lesson_key = 'chapter-04-lesson-02' and order_index = 4;
update public.ppg_lesson_steps set check_explanation_th = 'การจัดลำดับเลขบอกผู้ฟังว่าขั้นตอนใดมาก่อนหรือมาหลัง ขณะที่สัญลักษณ์แสดงหัวข้อไม่บอก' where lesson_key = 'chapter-04-lesson-02' and order_index = 5;
update public.ppg_lesson_steps set body_th = 'เน้นน้อยแต่ตรงจุด และเลือกรูปแบบรายการให้เหมาะกับความหมาย' where lesson_key = 'chapter-04-lesson-02' and order_index = 6;
update public.ppg_lesson_steps set body_th = 'เมื่อจบบทเรียนนี้คุณจะจัดข้อความ ตั้งระยะห่าง และใช้กล่องข้อความได้' where lesson_key = 'chapter-04-lesson-03' and order_index = 1;
update public.ppg_lesson_steps set body_th = 'จัดข้อความให้อยู่ในแนวเดียวกันทั้งสไลด์ และตั้งระยะห่างบรรทัดให้อ่านสบาย' where lesson_key = 'chapter-04-lesson-03' and order_index = 2;
update public.ppg_lesson_steps set body_th = 'ตัวอย่างสไลด์สรุปใช้หัวข้อชิดซ้าย เนื้อหาชิดซ้าย ระยะห่างบรรทัด 1.5 เท่า และเพิ่มกล่องข้อความสำหรับหมายเหตุท้ายสไลด์' where lesson_key = 'chapter-04-lesson-03' and order_index = 3;
update public.ppg_lesson_steps set body_th = 'เลือกข้อความ จากนั้นใช้แท็บ Home ตั้งค่า Align Left, Center หรือ Align Right ตั้ง Line Spacing ที่ Line Spacing และแทรกกล่องข้อความใหม่ที่ Insert > Text Box' where lesson_key = 'chapter-04-lesson-03' and order_index = 4;
update public.ppg_lesson_steps set check_prompt_th = 'ถ้าข้อความยาวเกินกล่องจนล้นออกมาควรทำอย่างไร' where lesson_key = 'chapter-04-lesson-03' and order_index = 5;
