update public.ppg_modules set summary_th = 'แทรกภาพจากไฟล์ จากออนไลน์ และจากคลิปอาร์ต แก้ไขภาพ รวมถึงแทรกและแก้ไขรูปร่างพร้อมใช้' where module_key = 'chapter-05';
update public.ppg_lessons set title_th = 'การแทรกภาพจากไฟล์ ออนไลน์ และคลิปอาร์ต' where lesson_key = 'chapter-05-lesson-01';
update public.ppg_lessons set body_th = 'ภาพจากสามแหล่งหลักคือไฟล์ในคอมพิวเตอร์ การค้นหาออนไลน์ และคลิปอาร์ตที่มีในโปรแกรม การแทรกภาพเริ่มจากแท็บ Insert จากนั้นเลือก Pictures และเลือกแหล่ง เช่น ไฟล์ ออนไลน์ หรือคลิปอาร์ต ตรวจใบอนุญาตและความละเอียดของภาพก่อนใช้กับข้อเสนอสำหรับลูกค้า' where lesson_key = 'chapter-05-lesson-01';
update public.ppg_lessons set what_next_th = 'ต่อไป: แก้ไขภาพด้วยการตัด การแก้ไข และเอฟเฟกต์' where lesson_key = 'chapter-05-lesson-01';
update public.ppg_lessons set title_th = 'การแก้ไขภาพ: การตัด ความสว่าง เอฟเฟกต์ และเค้าโครงภาพ' where lesson_key = 'chapter-05-lesson-02';
update public.ppg_lessons set what_learn_th = 'ตัดภาพ ปรับความสว่างและความคมชัด เพิ่มเอฟเฟกต์ และเลือกเค้าโครงภาพได้' where lesson_key = 'chapter-05-lesson-02';
update public.ppg_lessons set why_th = 'แก้ไขภาพดีทำให้เนื้อหาเด่นโดยไม่ต้องเปลี่ยนภาพใหม่' where lesson_key = 'chapter-05-lesson-02';
update public.ppg_lessons set body_th = 'การตัดคือการลดขอบของภาพที่ไม่ใช้ การแก้ไขปรับความสว่างและความคมชัด เอฟเฟกต์เปลี่ยนลักษณะของภาพ เช่น ดินสอสเก็ตช์ และเค้าโครงภาพวางภาพในกรอบข้างข้อความ' where lesson_key = 'chapter-05-lesson-02';
update public.ppg_lessons set what_learn_th = 'แทรกรูปร่างจากแกลเลอรี เปลี่ยนการเติมสีและเส้นขอบของรูปร่าง เพิ่มข้อความ และจัดวางลำดับได้' where lesson_key = 'chapter-05-lesson-03';
update public.ppg_lessons set why_th = 'รูปร่างช่วยอธิบายความสัมพันธ์ระหว่างแนวคิด เช่น ขั้นตอนในกระบวนการ' where lesson_key = 'chapter-05-lesson-03';
update public.ppg_lessons set body_th = 'รูปร่างพร้อมใช้มาจากแกลเลอรี Shapes เช่น ลูกศร กล่องคำพูด และกล่องข้อความ หลังแทรกแล้วสามารถเปลี่ยน Shape Fill, Shape Outline และเอฟเฟกต์ พิมพ์ข้อความในรูปร่าง และจัดลำดับด้วย Bring Forward, Send Backward หรือ Group' where lesson_key = 'chapter-05-lesson-03';
update public.ppg_lesson_steps set body_th = 'เมื่อจบบทเรียนนี้คุณจะแทรกภาพจากไฟล์ แหล่งออนไลน์ และคลิปอาร์ตได้' where lesson_key = 'chapter-05-lesson-01' and order_index = 1;
update public.ppg_lesson_steps set body_th = 'ทุกภาพจะกลายเป็นวัตถุที่สามารถย้าย ปรับขนาด และแก้ไขได้' where lesson_key = 'chapter-05-lesson-01' and order_index = 2;
update public.ppg_lesson_steps set body_th = 'ตัวอย่างทีมขายแทรกภาพสินค้าจากไฟล์ที่แชร์ลงในข้อเสนอ' where lesson_key = 'chapter-05-lesson-01' and order_index = 3;
update public.ppg_lesson_steps set body_th = 'ภาพออนไลน์มีลิขสิทธิ์จึงต้องตรวจใบอนุญาตก่อนใช้ เลือกภาพที่มีความชัดเพียงพอสำหรับสไลด์และการพิมพ์' where lesson_key = 'chapter-05-lesson-01' and order_index = 4;
update public.ppg_lesson_steps set check_prompt_th = 'ก่อนใช้ภาพออนไลน์ในข้อเสนอสำหรับลูกค้า ควรตรวจสิ่งใดก่อน' where lesson_key = 'chapter-05-lesson-01' and order_index = 5;
update public.ppg_lesson_steps set body_th = 'เลือกภาพจากแหล่งที่เหมาะสม ตรวจใบอนุญาต และแทรกเพื่ออธิบาย ไม่ใช่เพื่อตกแต่ง' where lesson_key = 'chapter-05-lesson-01' and order_index = 6;
update public.ppg_lesson_steps set body_th = 'เมื่อจบบทเรียนนี้คุณจะตัดภาพ ปรับความสว่าง เพิ่มเอฟเฟกต์ และเลือกเค้าโครงภาพได้' where lesson_key = 'chapter-05-lesson-02' and order_index = 1;
update public.ppg_lesson_steps set body_th = 'การตัดช่วยให้ผู้ฟังเห็นจุดหลัก การแก้ไขช่วยให้ภาพที่มืดหรือสว่างเกินไปอ่านง่ายขึ้น' where lesson_key = 'chapter-05-lesson-02' and order_index = 2;
update public.ppg_lesson_steps set body_th = 'ตัวอย่างสไลด์รายงานความก้าวหน้าตัดภาพโรงงานให้เหลือเฉพาะเครื่องจักร และปรับความสว่างให้มองเห็นชัดเจน' where lesson_key = 'chapter-05-lesson-02' and order_index = 3;
