update public.ppg_lesson_steps set check_prompt_th = 'เมื่อตัดภาพ ส่วนที่ไม่ใช้จะกลายเป็นอะไร' where lesson_key = 'chapter-05-lesson-02' and order_index = 5;
update public.ppg_lesson_steps set check_explanation_th = 'การตัดเพียงซ่อนขอบที่ไม่ใช้ ภาพยังคงอยู่ครบ จึงตัดอีกครั้งเพื่อกู้คืนได้' where lesson_key = 'chapter-05-lesson-02' and order_index = 5;
update public.ppg_lesson_steps set body_th = 'ตัดให้เหลือเฉพาะจุดสำคัญ ปรับความสว่างให้พอดี และใช้เอฟเฟกต์เมื่อช่วยเสริมเนื้อหาเท่านั้น' where lesson_key = 'chapter-05-lesson-02' and order_index = 6;
update public.ppg_lesson_steps set body_th = 'เมื่อจบบทเรียนนี้คุณจะแทรกรูปร่าง เปลี่ยนการเติมสีและเส้นขอบของรูปร่าง เพิ่มข้อความ และจัดวางลำดับได้' where lesson_key = 'chapter-05-lesson-03' and order_index = 1;
update public.ppg_lesson_steps set body_th = 'รูปร่างคือวัตถุที่สามารถปรับขนาด หมุน พลิก และจัดกลุ่มกับรูปร่างอื่นได้' where lesson_key = 'chapter-05-lesson-03' and order_index = 2;
