update public.ppg_lesson_steps set body_th = 'แทรกรูปร่างจากแกลเลอรี กำหนดการเติมสีและเส้นขอบของรูปร่าง และจัดวางลำดับด้วย Bring Forward หรือ Send Backward' where lesson_key = 'chapter-05-lesson-03' and order_index = 6;
