update public.ppg_modules set summary_th = 'การสร้างแผนภูมิและกราฟ แท็บ Chart Design และองค์ประกอบแผนภูมิ และการตกแต่งแผนภูมิในแท็บ Format' where module_key = 'chapter-06';
update public.ppg_lessons set why_th = 'แผนภูมิช่วยให้ผู้ฟังเห็นรูปแบบของตัวเลขได้อย่างรวดเร็ว' where lesson_key = 'chapter-06-lesson-01';
update public.ppg_lessons set body_th = 'แผนภูมิเปลี่ยนตารางตัวเลขให้กลายเป็นภาพ ประเภทที่ใช้บ่อยคือแผนภูมิคอลัมน์ แผนภูมิเส้น และแผนภูมิวงกลม เลือกแผนภูมิคอลัมน์เพื่อเปรียบเทียบค่า แผนภูมิเส้นเพื่อแสดงแนวโน้มตามเวลา และแผนภูมิวงกลมเพื่อแสดงส่วนของทั้งหมด' where lesson_key = 'chapter-06-lesson-01';
update public.ppg_lessons set why_th = 'องค์ประกอบที่เหมาะสมช่วยให้ผู้ฟังอ่านแผนภูมิได้โดยไม่ต้องอธิบายเพิ่ม' where lesson_key = 'chapter-06-lesson-02';
update public.ppg_lessons set what_learn_th = 'ใช้แท็บ Format เพื่อเปลี่ยนการเติมสี เส้นขอบ และเอฟเฟกต์ และตกแต่งแผนภูมิเพื่อให้จุดสำคัญเด่นขึ้นได้' where lesson_key = 'chapter-06-lesson-03';
update public.ppg_lessons set why_th = 'การตกแต่งมีประโยชน์ก็ต่อเมื่อทำให้จุดสำคัญมองเห็นได้ง่ายขึ้น' where lesson_key = 'chapter-06-lesson-03';
update public.ppg_lessons set body_th = 'แท็บ Format ตกแต่งองค์ประกอบแผนภูมิที่เลือก ได้แก่ Shape Fill, Shape Outline และ Shape Effects ใช้ Chart Styles เพื่อให้ได้ลักษณะที่สม่ำเสมออย่างรวดเร็ว ใช้สีให้น้อยลงและเน้นหนึ่งชุดข้อมูลเพื่อให้ข้อความชัดเจน' where lesson_key = 'chapter-06-lesson-03';
update public.ppg_lesson_steps set check_prompt_th = 'องค์ประกอบใดอธิบายว่าสีแต่ละสีหมายถึงอะไร' where lesson_key = 'chapter-06-lesson-02' and order_index = 5;
update public.ppg_lesson_steps set check_explanation_th = 'คำอธิบายบอกผู้ฟังว่าสีแต่ละสีหมายถึงอะไร ขณะที่ป้ายกำกับข้อมูลแสดงค่าและเส้นตารางช่วยอ่านค่า' where lesson_key = 'chapter-06-lesson-02' and order_index = 5;
update public.ppg_lesson_steps set body_th = 'เลือกแผนภูมิ เพิ่มเฉพาะองค์ประกอบที่ผู้ฟังต้องการ และตัดองค์ประกอบที่ไม่จำเป็นออก' where lesson_key = 'chapter-06-lesson-02' and order_index = 6;
update public.ppg_lesson_steps set body_th = 'เมื่อจบบทเรียนนี้คุณจะใช้แท็บ Format เพื่อเปลี่ยนการเติมสี เส้นขอบ และเอฟเฟกต์ และทำให้จุดสำคัญเด่นได้' where lesson_key = 'chapter-06-lesson-03' and order_index = 1;
update public.ppg_lesson_steps set body_th = 'แท็บ Format ใช้ตกแต่งทีละองค์ประกอบ การใช้รูปแบบเดียวที่สม่ำเสมอทั้งแผนภูมิจะอ่านง่ายกว่า' where lesson_key = 'chapter-06-lesson-03' and order_index = 2;
update public.ppg_lesson_steps set body_th = 'ตัวอย่าง: ทีมกำหนดให้ชุดข้อมูลหนึ่งเป็นสีน้ำเงินและชุดข้อมูลอื่นเป็นสีเทา เพื่อให้เส้นหลักเด่นขึ้น' where lesson_key = 'chapter-06-lesson-03' and order_index = 3;
