update public.ppg_lesson_steps set check_prompt_th = 'แผนภูมิรกเพราะใช้สีหลายสีเกินไป ควรแก้ไขอย่างไร' where lesson_key = 'chapter-06-lesson-03' and order_index = 5;
update public.ppg_lesson_steps set check_explanation_th = 'ใช้สีน้อยลงและเน้นชุดข้อมูลสำคัญ การเพิ่มป้ายกำกับหรือลดขนาดแบบอักษรไม่ได้ช่วยให้แผนภูมิที่รกดีขึ้น' where lesson_key = 'chapter-06-lesson-03' and order_index = 5;
update public.ppg_lesson_steps set body_th = 'ตกแต่งแผนภูมิเพื่อให้ข้อความชัดเจน ไม่ใช่เพื่อใส่สีให้เยอะ' where lesson_key = 'chapter-06-lesson-03' and order_index = 6;
