update public.ppg_lessons set why_th = 'SmartArt ช่วยให้สร้างแผนภาพที่จัดวางอัตโนมัติโดยไม่ต้องวาดด้วยมือเอง' where lesson_key = 'chapter-07-lesson-02';
update public.ppg_lessons set body_th = 'SmartArt คือชุดแผนภาพพร้อมใช้ที่แทรกจากแท็บ Insert จากนั้นเลือกชนิด เช่น กระบวนการ ลำดับขั้น หรือวัฏจักร หลังแทรกจะมีกล่องข้อความให้พิมพ์ และมีคำสั่ง Add Shape, Promote, Demote และเปลี่ยนสี แผนผังองค์กรคือ SmartArt ชนิดลำดับขั้นที่ใช้แสดงสายงานและผู้รับผิดชอบ' where lesson_key = 'chapter-07-lesson-02';
update public.ppg_lessons set why_th = 'ตารางจัดวางข้อมูลให้เป็นระเบียบและเปรียบเทียบได้ง่าย' where lesson_key = 'chapter-07-lesson-03';
update public.ppg_lessons set body_th = 'ตารางใช้เมื่อต้องแสดงข้อมูลหลายค่าที่ต้องเปรียบเทียบกัน เช่น ราคา จำนวน หรือกำหนดเวลา แทรกตารางจากแท็บ Insert โดยเลือก Table จากนั้นลากเลือกช่องหรือพิมพ์จำนวนแถวและคอลัมน์ แต่ละช่องเรียกว่าเซลล์ ใช้แท็บ Table Design และ Layout เพื่อเพิ่มหรือลบแถวและคอลัมน์ รวมเซลล์และเลือกสีตาราง' where lesson_key = 'chapter-07-lesson-03';
update public.ppg_lesson_steps set body_th = 'แผนภาพใช้เมื่อความคิดมีความสัมพันธ์กัน เช่น ลำดับ วัฏจักร หรือโครงสร้าง' where lesson_key = 'chapter-07-lesson-01' and order_index = 2;
update public.ppg_lesson_steps set body_th = 'ตัวอย่าง: ทีมขายใช้แผนภาพกระบวนการห้าขั้นตอนเพื่ออธิบายการอนุมัติสินเชื่อ' where lesson_key = 'chapter-07-lesson-01' and order_index = 3;
update public.ppg_lesson_steps set body_th = 'เลือกรูปแบบตามความสัมพันธ์ ไม่ใช่ตามความสวยงาม ถ้าเป็นลำดับให้ใช้กระบวนการ ถ้าเป็นการวนซ้ำให้ใช้วัฏจักร' where lesson_key = 'chapter-07-lesson-01' and order_index = 4;
update public.ppg_lesson_steps set check_explanation_th = 'วัฏจักรแสดงความคิดที่วนกลับไปยังจุดเริ่มต้น กระบวนการแสดงลำดับที่จบ' where lesson_key = 'chapter-07-lesson-01' and order_index = 5;
update public.ppg_lesson_steps set body_th = 'เลือกแผนภาพให้ตรงกับความสัมพันธ์ แล้วให้ผู้ฟังเห็นภาพได้ในครั้งเดียว' where lesson_key = 'chapter-07-lesson-01' and order_index = 6;
update public.ppg_lesson_steps set body_th = 'SmartArt เปลี่ยนรายการข้อความให้เป็นแผนภาพ และจัดวางพร้อมเชื่อมต่อรูปร่างให้เอง' where lesson_key = 'chapter-07-lesson-02' and order_index = 2;
update public.ppg_lesson_steps set body_th = 'ตัวอย่าง: แผนกบุคคลใช้แผนผังองค์กรเพื่อแสดงหัวหน้าและทีมในบริษัท' where lesson_key = 'chapter-07-lesson-02' and order_index = 3;
update public.ppg_lesson_steps set body_th = 'เลือก SmartArt แล้วพิมพ์รายการในกล่องข้อความ ใช้ Add Shape เพื่อเพิ่มตำแหน่ง และใช้ Promote หรือ Demote เพื่อจัดวางสายงาน' where lesson_key = 'chapter-07-lesson-02' and order_index = 4;
update public.ppg_lesson_steps set check_explanation_th = 'เพิ่มรูปร่างใหม่ แล้วใช้ Demote เพื่อให้อยู่ใต้ตำแหน่งที่เลือก' where lesson_key = 'chapter-07-lesson-02' and order_index = 5;
update public.ppg_lesson_steps set body_th = 'SmartArt ทำให้แผนภาพเร็วและสม่ำเสมอ แต่ยังต้องจัดวางลำดับขั้นให้ตรงกับสายงานจริง' where lesson_key = 'chapter-07-lesson-02' and order_index = 6;
update public.ppg_lesson_steps set body_th = 'คลิกในเซลล์แล้วพิมพ์ข้อมูล ใช้แท็บ Layout เพื่อเพิ่มแถวหรือคอลัมน์ และใช้รวมเซลล์เมื่อต้องการช่องที่กว้างขึ้น' where lesson_key = 'chapter-07-lesson-03' and order_index = 4;
update public.ppg_lesson_steps set check_explanation_th = 'รวมเซลล์ทำให้สองช่องเป็นช่องเดียว เหมาะกับหัวตารางที่คร่อมหลายคอลัมน์' where lesson_key = 'chapter-07-lesson-03' and order_index = 5;
update public.ppg_lesson_steps set body_th = 'ปรับขนาดตารางให้พอดีกับข้อมูล ใช้หัวตารางและเส้นขอบให้ชัดเจน และรวมเซลล์เมื่อจำเป็นเท่านั้น' where lesson_key = 'chapter-07-lesson-03' and order_index = 6;
update public.ppg_knowledge_missions set instructions_th = 'ภารกิจความรู้: ตอบคำถามหกข้อเกี่ยวกับแผนภาพ SmartArt และตาราง ต้องได้ 70% จึงจะผ่าน และทำซ้ำได้ไม่จำกัด' where module_key = 'chapter-07';
update public.ppg_knowledge_mission_questions set prompt_th = 'แผนภาพมีประโยชน์อย่างไร' where module_key = 'chapter-07' and order_index = 1;
update public.ppg_knowledge_mission_questions set option_th = 'อธิบายด้วยข้อความยาว ๆ' where module_key = 'chapter-07' and order_index = 1 and option_key = 'b';
update public.ppg_knowledge_mission_questions set option_th = 'ระบุแหล่งที่มาของข้อมูล' where module_key = 'chapter-07' and order_index = 1 and option_key = 'c';
update public.ppg_knowledge_mission_questions set explanation_th = 'ลำดับขั้นแสดงตำแหน่งและสายงาน วัฏจักรแสดงการวนซ้ำ กระบวนการแสดงลำดับของขั้นตอน' where module_key = 'chapter-07' and order_index = 2;
update public.ppg_knowledge_mission_questions set explanation_th = 'แทรก SmartArt จากแท็บ Insert แล้วเลือกชนิดแผนภาพ' where module_key = 'chapter-07' and order_index = 3;
update public.ppg_knowledge_mission_questions set prompt_th = 'คำสั่งใดทำให้ตำแหน่งใหม่อยู่ใต้ตำแหน่งที่เลือก' where module_key = 'chapter-07' and order_index = 4;
update public.ppg_knowledge_mission_questions set explanation_th = 'Demote ทำให้ตำแหน่งใหม่อยู่ใต้ตำแหน่งที่เลือก ส่วน Promote ทำให้เลื่อนขึ้นหนึ่งระดับ' where module_key = 'chapter-07' and order_index = 4;
update public.ppg_knowledge_mission_questions set prompt_th = 'เมื่อจะแทรกตาราง ควรเริ่มจากที่ไหน' where module_key = 'chapter-07' and order_index = 5;
update public.ppg_knowledge_mission_questions set option_th = 'แท็บ Insert จากนั้น Table' where module_key = 'chapter-07' and order_index = 5 and option_key = 'a';
update public.ppg_knowledge_mission_questions set explanation_th = 'แทรกตารางจากแท็บ Insert โดยเลือก Table จากนั้นลากเลือกช่องหรือพิมพ์จำนวนแถวและคอลัมน์' where module_key = 'chapter-07' and order_index = 5;
update public.ppg_knowledge_mission_questions set option_th = 'แท็บ Insert จากนั้น Chart' where module_key = 'chapter-07' and order_index = 5 and option_key = 'c';
