update public.ppg_chapter_test_questions set option_th = 'ไม่ต้องใช้สีเลย' where chapter_key = 'chapter-07' and phase = 'pre' and order_index = 8 and option_key = 'c';
update public.ppg_chapter_test_questions set option_th = 'ทำให้สไลด์ยาวขึ้น' where chapter_key = 'chapter-07' and phase = 'post' and order_index = 1 and option_key = 'b';
update public.ppg_chapter_test_questions set prompt_th = 'คำสั่งใดเลื่อนรูปร่างขึ้นหนึ่งระดับ' where chapter_key = 'chapter-07' and phase = 'post' and order_index = 4;
update public.ppg_chapter_test_questions set prompt_th = 'ในตาราง เซลล์คืออะไร' where chapter_key = 'chapter-07' and phase = 'post' and order_index = 7;
update public.ppg_chapter_test_questions set option_th = 'ช่องที่เกิดจากแถวและคอลัมน์ตัดกัน' where chapter_key = 'chapter-07' and phase = 'post' and order_index = 7 and option_key = 'a';
update public.ppg_chapter_test_questions set option_th = 'หัวตารางชัดเจนและเส้นขอบที่พอดี' where chapter_key = 'chapter-07' and phase = 'post' and order_index = 10 and option_key = 'a';
update public.ppg_chapter_test_questions set option_th = 'ใส่สีทุกเซลล์' where chapter_key = 'chapter-07' and phase = 'post' and order_index = 10 and option_key = 'b';
update public.ppg_chapter_test_questions set option_th = 'แบบอักษรที่เล็กลง' where chapter_key = 'chapter-07' and phase = 'post' and order_index = 10 and option_key = 'c';
update public.ppg_lessons set body_th = 'การเปลี่ยนสไลด์คือเอฟเฟกต์ที่เกิดเมื่อเปลี่ยนจากสไลด์หนึ่งไปยังสไลด์อื่น ใส่จากแท็บ Transitions จากนั้นเลือกจากแกลเลอรี ตั้งระยะเวลา และเลือกว่าจะเปลี่ยนเมื่อคลิกหรืออัตโนมัติ ใช้การเปลี่ยนสไลด์แบบเดียวทั้งชุด และให้สั้นพอเพื่อไม่ให้รบกวนเนื้อหา' where lesson_key = 'chapter-08-lesson-01';
update public.ppg_lessons set what_next_th = 'ต่อไป: แอนิเมชัน เส้นทางการเคลื่อนที่ และทริกเกอร์' where lesson_key = 'chapter-08-lesson-01';
update public.ppg_lessons set body_th = 'แอนิเมชันคือเอฟเฟกต์ที่เกิดกับวัตถุบนสไลด์ เช่น ข้อความ ภาพ หรือแผนภูมิ มีสามกลุ่มคือทางเข้า ทางออก และการเน้น ใส่จากแท็บ Animations จากนั้นใช้ Animation Pane จัดวางลำดับ ตั้งให้เริ่มเมื่อคลิก พร้อมกัน หรือหลังรายการก่อนหน้า เส้นทางการเคลื่อนที่ทำให้วัตถุย้ายตามเส้นทาง และทริกเกอร์ (Trigger) ทำให้เอฟเฟกต์เริ่มเมื่อเกิดเหตุการณ์ เช่น คลิกวัตถุหนึ่ง' where lesson_key = 'chapter-08-lesson-02';
update public.ppg_lessons set what_next_th = 'ต่อไป: เอฟเฟกต์สำหรับแผนภูมิ SmartArt และแผนผังองค์กร รวมถึงมัลติมีเดีย' where lesson_key = 'chapter-08-lesson-02';
update public.ppg_lessons set what_learn_th = 'เพิ่มแอนิเมชันในแผนภูมิและ SmartArt แทรกเสียงหรือวิดีโอ และตั้งวิธีเล่นได้' where lesson_key = 'chapter-08-lesson-03';
update public.ppg_lessons set why_th = 'มัลติมีเดียที่เหมาะสมช่วยอธิบายให้ชัดเจน แต่มากเกินไปจะรบกวนผู้ฟัง' where lesson_key = 'chapter-08-lesson-03';
update public.ppg_lessons set body_th = 'แผนภูมิและ SmartArt มีแอนิเมชันเฉพาะ เช่น ให้ชุดข้อมูลเข้าทีละรายการ หรือให้แต่ละสาขาของแผนผังองค์กรปรากฏตามลำดับ ใช้ตัวเลือกเอฟเฟกต์ (Effect Options) เพื่อเลือกวิธีนี้ แทรกเสียงหรือวิดีโอจากแท็บ Insert จากนั้นตั้งการเล่นอัตโนมัติหรือเมื่อคลิก ใช้เสียงบรรยายเมื่อสอนออนไลน์ และปิดเสียงเมื่อไม่จำเป็น' where lesson_key = 'chapter-08-lesson-03';
update public.ppg_lesson_steps set body_th = 'ใช้แอนิเมชันน้อยแต่ให้ตรงจังหวะ ตั้งทริกเกอร์เมื่อจำเป็น และตรวจลำดับใน Animation Pane' where lesson_key = 'chapter-08-lesson-02' and order_index = 6;
update public.ppg_lesson_steps set body_th = 'ตัวอย่าง: ชุดสไลด์อบรมใช้การเปลี่ยนสไลด์แบบจางทุกสไลด์เพื่อไม่ดึงความสนใจ' where lesson_key = 'chapter-08-lesson-01' and order_index = 3;
update public.ppg_lesson_steps set body_th = 'ตั้งระยะเวลาให้สั้น เช่น ครึ่งวินาที และเลือกเปลี่ยนเมื่อคลิกเพื่อให้ผู้บรรยายควบคุมจังหวะ' where lesson_key = 'chapter-08-lesson-01' and order_index = 4;
update public.ppg_lesson_steps set body_th = 'ใช้การเปลี่ยนสไลด์แบบเดียวทั้งชุด ให้สั้นและสม่ำเสมอ เพื่อให้เนื้อหาเด่น' where lesson_key = 'chapter-08-lesson-01' and order_index = 6;
update public.ppg_lesson_steps set body_th = 'ทางเข้าทำให้วัตถุปรากฏ ทางออกทำให้วัตถุหาย และการเน้นดึงสายตาขณะที่วัตถุยังอยู่' where lesson_key = 'chapter-08-lesson-02' and order_index = 2;
update public.ppg_lesson_steps set body_th = 'ตัวอย่าง: รายงานความก้าวหน้านำตัวเลขยอดขายเข้าทีละรายการเพื่อให้ผู้ฟังเห็นประเด็น' where lesson_key = 'chapter-08-lesson-02' and order_index = 3;
update public.ppg_lesson_steps set body_th = 'ใช้ Animation Pane จัดลำดับ ตั้งให้เริ่มเมื่อคลิก พร้อมกับรายการก่อนหน้า หรือหลังรายการก่อนหน้า และใช้เส้นทางการเคลื่อนที่เพื่อย้ายวัตถุไปตามเส้นทาง' where lesson_key = 'chapter-08-lesson-02' and order_index = 4;
update public.ppg_lesson_steps set check_explanation_th = 'ทางออกทำให้วัตถุหาย ขณะที่ทางเข้าทำให้ปรากฏ และการเน้นดึงสายตา' where lesson_key = 'chapter-08-lesson-02' and order_index = 5;
update public.ppg_lesson_steps set body_th = 'ตัวเลือกเอฟเฟกต์เปลี่ยนวิธีที่ชุดข้อมูลหรือสาขาปรากฏ เช่น ทีละรายการหรือตามหมวด' where lesson_key = 'chapter-08-lesson-03' and order_index = 2;
update public.ppg_lesson_steps set body_th = 'ตัวอย่าง: สไลด์แนะนำบริษัทนำแต่ละสาขาของแผนผังองค์กรเข้าตามลำดับจากบนลงล่าง' where lesson_key = 'chapter-08-lesson-03' and order_index = 3;
update public.ppg_lesson_steps set body_th = 'ใช้เอฟเฟกต์และมัลติมีเดียเพื่ออธิบาย ไม่ใช่เพื่อความตื่นเต้น และปิดเสียงเมื่อไม่จำเป็น' where lesson_key = 'chapter-08-lesson-03' and order_index = 6;
update public.ppg_knowledge_missions set instructions_th = 'ภารกิจความรู้: ตอบคำถามหกข้อเกี่ยวกับการเปลี่ยนสไลด์ แอนิเมชัน และมัลติมีเดีย ผ่านเกณฑ์ 70% และทำซ้ำได้ไม่จำกัด' where module_key = 'chapter-08';
