update public.ppg_chapter_test_questions set option_th = 'ผู้ฟังอ่านสไลด์ไม่ทัน' where chapter_key = 'chapter-08' and phase = 'post' and order_index = 1 and option_key = 'b';
update public.ppg_chapter_test_questions set option_th = 'จัดลำดับใหม่ใน Animation Pane' where chapter_key = 'chapter-08' and phase = 'post' and order_index = 6 and option_key = 'a';
update public.ppg_chapter_test_questions set option_th = 'เสียงชัดเจนและมีความยาวพอดี' where chapter_key = 'chapter-08' and phase = 'post' and order_index = 10 and option_key = 'a';
update public.ppg_lessons set what_learn_th = 'อธิบายว่าเอกสารประกอบและเอกสารแจกคืออะไร และเลือกเอกสารที่จะเตรียมให้ผู้ฟังได้' where lesson_key = 'chapter-09-lesson-01';
update public.ppg_lessons set why_th = 'เอกสารประกอบช่วยผู้ฟังติดตามและจดจำประเด็นหลักหลังการนำเสนอได้' where lesson_key = 'chapter-09-lesson-01';
update public.ppg_lessons set body_th = 'เอกสารประกอบคือเอกสารที่ใช้กับการนำเสนอ เช่น เอกสารแจก (Handout) บันทึกผู้นำเสนอ หรือรายงาน เอกสารแจกคือหน้าสรุปที่ให้ผู้ฟัง มีประเด็นหลัก ข้อมูลและพื้นที่จดบันทึก ไม่ใช่คัดลอกทุกสไลด์ เตรียมก่อนวันนำเสนอ ตรวจตัวเลข และทำสองฉบับ หนึ่งสำหรับผู้ฟังและหนึ่งสำหรับผู้บรรยาย' where lesson_key = 'chapter-09-lesson-01';
update public.ppg_lessons set why_th = 'การซ้อมและการควบคุมเวลาทำให้คุณเสร็จตรงเวลาและทำให้ผู้ฟังติดตามคุณได้' where lesson_key = 'chapter-09-lesson-02';
update public.ppg_lessons set body_th = 'ก่อนนำเสนอ ตรวจอุปกรณ์ เปิดไฟล์ เริ่ม Slide Show จากสไลด์แรก มุมมองผู้นำเสนอแสดงบันทึกและสไลด์ต่อไปสำหรับผู้บรรยาย ขณะที่ผู้ฟังเห็นสไลด์เท่านั้น ซ้อมออกเสียงกับนาฬิกาจับเวลาและตั้งเป้าให้เสร็จก่อนเวลา จากนั้นกำหนดจุดที่ต้องช้าลงหรือตัดออก ขณะที่นำเสนอ สบตากับผู้ฟัง พูดด้วยจังหวะสม่ำเสมอ หยุดที่ประเด็นหลัก และดูนาฬิกาจับเวลาในมุมมองผู้นำเสนอ' where lesson_key = 'chapter-09-lesson-02';
update public.ppg_lessons set why_th = 'งานธุรกิจดิจิทัลมักมีการนำเสนอออนไลน์ แชร์ไฟล์ หรือส่งชุดสไลด์ที่ผู้ฟังเปิดภายหลัง' where lesson_key = 'chapter-09-lesson-03';
update public.ppg_lesson_steps set body_th = 'เมื่อจบบทเรียนนี้คุณจะอธิบายเอกสารประกอบและเอกสารแจก และเลือกได้ว่าจะเตรียมอะไร' where lesson_key = 'chapter-09-lesson-01' and order_index = 1;
update public.ppg_lesson_steps set check_explanation_th = 'เอกสารแจกคือหน้าสรุปสำหรับผู้ฟัง บันทึกผู้นำเสนอสำหรับผู้บรรยาย และการพิมพ์ทุกสไลด์ไม่ใช่เอกสารแจก' where lesson_key = 'chapter-09-lesson-01' and order_index = 5;
update public.ppg_lesson_steps set body_th = 'ตัวอย่าง: การอบรมหนึ่งครั้งมีการซ้อมกับนาฬิกาจับเวลาและเสร็จก่อนเวลาสองนาทีเพื่อให้มีเวลาสำหรับคำถาม' where lesson_key = 'chapter-09-lesson-02' and order_index = 3;
update public.ppg_lesson_steps set check_explanation_th = 'มุมมองผู้นำเสนอแสดงบันทึกและสไลด์ต่อไปสำหรับผู้บรรยาย Slide Sorter แสดงสไลด์ทั้งหมด และ Notes Page แสดงหน้าโน้ต' where lesson_key = 'chapter-09-lesson-02' and order_index = 5;
update public.ppg_lesson_steps set body_th = 'เลือกผลลัพธ์ที่เหมาะสม: PDF สำหรับการอ่าน ลิงก์สำหรับผู้ฟังออนไลน์ และไฟล์สไลด์สำหรับผู้บรรยาย' where lesson_key = 'chapter-09-lesson-03' and order_index = 4;
update public.ppg_lesson_steps set body_th = 'เตรียมเอกสารและซ้อม นำเสนอโดยใช้มุมมองผู้นำเสนอและแชร์หน้าจอ จากนั้นติดตามด้วย PDF และข้อมูลติดต่อ สถานการณ์นี้เตรียมคุณสำหรับข้อสอบสุดท้าย' where lesson_key = 'chapter-09-lesson-03' and order_index = 6;
update public.ppg_lesson_step_options set option_th = 'Slide Sorter' where lesson_key = 'chapter-09-lesson-02' and step_order_index = 5 and option_key = 'b';
update public.ppg_lesson_step_options set option_th = 'Notes Page' where lesson_key = 'chapter-09-lesson-02' and step_order_index = 5 and option_key = 'c';
update public.ppg_knowledge_missions set instructions_th = 'ภารกิจความรู้: ตอบคำถามหกข้อเกี่ยวกับเอกสารประกอบ เอกสารแจก การนำเสนอ และงานธุรกิจดิจิทัล ผ่านเกณฑ์ 70% และทำซ้ำได้ไม่จำกัด' where module_key = 'chapter-09';
update public.ppg_knowledge_mission_questions set option_th = 'เพื่อเพิ่มจำนวนสไลด์' where module_key = 'chapter-09' and order_index = 4 and option_key = 'b';
update public.ppg_knowledge_mission_questions set option_th = 'เตรียมเอกสาร ซ้อม และแชร์ลิงก์' where module_key = 'chapter-09' and order_index = 6 and option_key = 'a';
update public.ppg_knowledge_mission_questions set explanation_th = 'ก่อนประชุมควรเตรียมเอกสาร ซ้อมกับนาฬิกาจับเวลา และแชร์ลิงก์สำหรับคนที่เข้าร่วมออนไลน์' where module_key = 'chapter-09' and order_index = 6;
