update public.ppg_chapter_test_questions set option_th = 'แผนภูมิ เอกสารแจกแบบ PDF ลิงก์ และการซ้อม' where chapter_key = 'chapter-09' and phase = 'pre' and order_index = 10 and option_key = 'a';
update public.ppg_chapter_test_questions set option_th = 'รหัสผ่านใหม่' where chapter_key = 'chapter-09' and phase = 'post' and order_index = 5 and option_key = 'c';
update public.ppg_chapter_test_questions set option_th = 'ออกเสียงพร้อมจับเวลา' where chapter_key = 'chapter-09' and phase = 'post' and order_index = 6 and option_key = 'a';
update public.ppg_chapter_test_questions set prompt_th = 'ถ้าเริ่มช้ากว่ากำหนด ควรทำอะไร' where chapter_key = 'chapter-09' and phase = 'post' and order_index = 7;
update public.ppg_chapter_test_questions set option_th = 'เพิ่มสไลด์ให้มากขึ้น' where chapter_key = 'chapter-09' and phase = 'post' and order_index = 7 and option_key = 'b';
update public.ppg_chapter_test_questions set prompt_th = 'อะไรช่วยให้ผู้ฟังติดตามคุณตลอดเวลา' where chapter_key = 'chapter-09' and phase = 'post' and order_index = 8;
