update public.ppg_pretest_instruments set items = '[{"en":{"prompt":"What is a presentation?","choices":{"A":"Communicating one idea so the audience understands and can act on it.","B":"Reading a document aloud to the audience.","C":"Decorating slides so they look beautiful."}},"id":"item_1","th":{"prompt":"การนำเสนอคืออะไร","choices":{"A":"การสื่อสารความคิดหนึ่งเรื่องให้ผู้ฟังเข้าใจและนำไปใช้","B":"อ่านเอกสารออกเสียงให้ผู้ฟังฟัง","C":"ตกแต่งสไลด์ให้สวย"}},"chapter_key":"chapter-01","objective_key":"definition"},{"en":{"prompt":"What is a storyboard?","choices":{"A":"A finished slide template.","B":"A list of fonts used in the file.","C":"A plan of the presentation shown slide by slide."}},"id":"item_2","th":{"prompt":"สตอรีบอร์ดคืออะไร","choices":{"A":"แม่แบบสไลด์ที่เสร็จสมบูรณ์","B":"รายการแบบอักษรที่ใช้ในไฟล์","C":"แผนของการนำเสนอที่แสดงสไลด์ทีละสไลด์"}},"chapter_key":"chapter-02","objective_key":"sb_definition"},{"en":{"prompt":"Which is presentation software?","choices":{"A":"A printer and a scanner.","B":"PowerPoint, Google Slides, and Keynote.","C":"Excel and a calculator."}},"id":"item_3","th":{"prompt":"โปรแกรมนำเสนอคือข้อใด","choices":{"A":"เครื่องพิมพ์และเครื่องสแกน","B":"PowerPoint, Google Slides และ Keynote","C":"Excel และเครื่องคิดเลข"}},"chapter_key":"chapter-03","objective_key":"program_types"},{"en":{"prompt":"What is a text box used for?","choices":{"A":"Holding text at a position you choose on the slide.","B":"Playing background music.","C":"Saving the file to a folder."}},"id":"item_4","th":{"prompt":"กล่องข้อความใช้เพื่ออะไร","choices":{"A":"วางข้อความในตำแหน่งที่เลือกบนสไลด์","B":"เล่นเพลงพื้นหลัง","C":"บันทึกไฟล์ลงโฟลเดอร์"}},"chapter_key":"chapter-04","objective_key":"text_boxes"},{"en":{"prompt":"Which is a safe source of pictures for work?","choices":{"A":"Any image from a random website.","B":"A screenshot of a paid course.","C":"A company photo library with permission."}},"id":"item_5","th":{"prompt":"แหล่งรูปภาพที่ปลอดภัยสำหรับงานคือข้อใด","choices":{"A":"ภาพใด ๆ จากเว็บไซต์แบบสุ่ม","B":"ภาพหน้าจอของคอร์สที่ต้องจ่ายเงิน","C":"คลังภาพของบริษัทที่ได้รับอนุญาต"}},"chapter_key":"chapter-05","objective_key":"picture_sources"},{"en":{"prompt":"When is a chart better than a table?","choices":{"A":"When the data has only one value.","B":"When you need to show a trend or a comparison quickly.","C":"When you need exact numbers in every cell."}},"id":"item_6","th":{"prompt":"เมื่อใดแผนภูมิดีกว่าตาราง","choices":{"A":"เมื่อข้อมูลมีเพียงค่าหนึ่ง","B":"เมื่อต้องแสดงแนวโน้มหรือการเปรียบเทียบอย่างรวดเร็ว","C":"เมื่อต้องมีตัวเลขที่แม่นยำในทุกช่อง"}},"chapter_key":"chapter-06","objective_key":"chart_purpose"},{"en":{"prompt":"When is a table the right choice?","choices":{"A":"When the audience needs exact values side by side.","B":"When you want to tell a story with photos.","C":"When the slide has no data."}},"id":"item_7","th":{"prompt":"เมื่อใดควรใช้ตาราง","choices":{"A":"เมื่อผู้ฟังต้องเห็นค่าที่แม่นยำเทียบกัน","B":"เมื่อต้องการเล่าเรื่องด้วยรูปภาพ","C":"เมื่อสไลด์ไม่มีข้อมูล"}},"chapter_key":"chapter-07","objective_key":"table_use"},{"en":{"prompt":"Why use a slide transition?","choices":{"A":"To make every slide spin.","B":"To hide the content.","C":"To signal a change between slides without distracting."}},"id":"item_8","th":{"prompt":"ทำไมใช้ทรานซิชันสไลด์","choices":{"A":"เพื่อทำให้ทุกสไลด์หมุน","B":"เพื่อซ่อนเนื้อหา","C":"เพื่อบอกการเปลี่ยนระหว่างสไลด์โดยไม่รบกวน"}},"chapter_key":"chapter-08","objective_key":"transition_purpose"},{"en":{"prompt":"What helps you speak clearly during a presentation?","choices":{"A":"Turning your back to the audience.","B":"Speaking slowly, pausing, and looking at the audience.","C":"Reading every word from the slide."}},"id":"item_9","th":{"prompt":"อะไรช่วยให้พูดชัดเจนระหว่างการนำเสนอ","choices":{"A":"หันหลังให้ผู้ฟัง","B":"พูดช้า ๆ หยุดและมองผู้ฟัง","C":"อ่านทุกคำจากสไลด์"}},"chapter_key":"chapter-09","objective_key":"delivery_skills"},{"en":{"prompt":"Which is a storyboard component?","choices":{"A":"The order of slides and the message on each slide.","B":"The colour of the office wall.","C":"The price of the projector."}},"id":"item_10","th":{"prompt":"องค์ประกอบของสตอรีบอร์ดคือข้อใด","choices":{"A":"ลำดับของสไลด์และข้อความบนแต่ละสไลด์","B":"สีของผนังสำนักงาน","C":"ราคาของเครื่องฉาย"}},"chapter_key":"chapter-02","objective_key":"sb_components"},{"en":{"prompt":"A learner knows PowerPoint. Which program is an equivalent?","choices":{"A":"Photoshop.","B":"Notepad.","C":"LibreOffice Impress."}},"id":"item_11","th":{"prompt":"ผู้เรียนใช้ PowerPoint แล้ว โปรแกรมใดเทียบเท่าได้","choices":{"A":"Photoshop","B":"Notepad","C":"LibreOffice Impress"}},"chapter_key":"chapter-03","objective_key":"program_equivalents"},{"en":{"prompt":"When is a bullet list the right choice?","choices":{"A":"When the slide has no title.","B":"When several short points share one main idea.","C":"When you need a full paragraph on every line."}},"id":"item_12","th":{"prompt":"เมื่อใดควรใช้รายการแบบจุด","choices":{"A":"เมื่อสไลด์ไม่มีชื่อเรื่อง","B":"เมื่อประเด็นสั้นหลายข้อมีใจความหลักเดียวกัน","C":"เมื่อต้องมีย่อหน้าเต็มในทุกบรรทัด"}},"chapter_key":"chapter-04","objective_key":"bullets"},{"en":{"prompt":"How do you insert a picture in PowerPoint?","choices":{"A":"Insert > Pictures, then choose the file.","B":"Design > Slide Size.","C":"View > Notes Page."}},"id":"item_13","th":{"prompt":"แทรกรูปภาพใน PowerPoint อย่างไร","choices":{"A":"Insert > Pictures แล้วเลือกไฟล์","B":"Design > Slide Size","C":"View > Notes Page"}},"chapter_key":"chapter-05","objective_key":"insert_path"},{"en":{"prompt":"Which chart best shows a trend over time?","choices":{"A":"A pie chart.","B":"A table of names.","C":"A line chart."}},"id":"item_14","th":{"prompt":"แผนภูมิข้อใดแสดงแนวโน้มเมื่อเวลาผ่านไปได้ดีที่สุด","choices":{"A":"แผนภูมิวงกลม","B":"ตารางรายชื่อ","C":"แผนภูมิเส้น"}},"chapter_key":"chapter-06","objective_key":"chart_types"},{"en":{"prompt":"How do you add a table in PowerPoint?","choices":{"A":"File > Print.","B":"Insert > Table, then choose the rows and columns.","C":"Home > New Slide."}},"id":"item_15","th":{"prompt":"เพิ่มตารางใน PowerPoint อย่างไร","choices":{"A":"File > Print","B":"Insert > Table แล้วเลือกแถวและคอลัมน์","C":"Home > New Slide"}},"chapter_key":"chapter-07","objective_key":"table_create"},{"en":{"prompt":"How do you apply one transition to all slides?","choices":{"A":"Choose the transition, then Apply To All.","B":"Change the slide master font.","C":"Delete the animation pane."}},"id":"item_16","th":{"prompt":"ใช้ทรานซิชันเดียวกับทุกสไลด์อย่างไร","choices":{"A":"เลือกทรานซิชันแล้วใช้กับทั้งหมด","B":"เปลี่ยนแบบอักษรของสไลด์ต้นแบบ","C":"ลบบานหน้าต่างแอนิเมชัน"}},"chapter_key":"chapter-08","objective_key":"transition_apply"},{"en":{"prompt":"What should you check before the audience arrives?","choices":{"A":"The office coffee machine.","B":"The colour of the chairs.","C":"The projector, the sound, and the clicker."}},"id":"item_17","th":{"prompt":"ก่อนผู้ฟังมาถึงควรตรวจสอบอะไร","choices":{"A":"เครื่องชงกาแฟของสำนักงาน","B":"สีของเก้าอี้","C":"เครื่องฉาย เสียง และรีโมท"}},"chapter_key":"chapter-09","objective_key":"delivery_setup"},{"en":{"prompt":"Which is a purpose of a presentation?","choices":{"A":"To postpone a decision.","B":"To inform, persuade, train, or report.","C":"To keep the information to yourself."}},"id":"item_18","th":{"prompt":"จุดประสงค์ของการนำเสนอคือข้อใด","choices":{"A":"เลื่อนการตัดสินใจออกไป","B":"ให้ข้อมูล โน้มน้าว ฝึกอบรม หรือรายงาน","C":"รักษาข้อมูลไว้คนเดียว"}},"chapter_key":"chapter-01","objective_key":"purposes"},{"en":{"prompt":"What is the usual first step when creating a new presentation?","choices":{"A":"Choose a blank file or a template that fits the work.","B":"Start adding animation to every object.","C":"Print the file before writing."}},"id":"item_19","th":{"prompt":"เมื่อสร้างการนำเสนอใหม่ ขั้นตอนแรกมักเป็นอะไร","choices":{"A":"เลือกไฟล์ว่างหรือแม่แบบที่เหมาะกับงาน","B":"เริ่มเพิ่มแ