rompt":"องค์ประกอบข้อใดบอกผู้อ่านว่าแผนภูมิวัดอะไร","choices":{"A":"ขอบของสไลด์","B":"ชื่อของผู้บรรยาย","C":"ป้ายแกนและชื่อเรื่องของแผนภูมิ"}},"chapter_key":"chapter-06","objective_key":"chart_elements"},{"en":{"prompt":"What is a diagram used for?","choices":{"A":"Replacing the presentation title.","B":"Showing how parts relate or how a process flows.","C":"Storing the raw sales data."}},"id":"item_39","th":{"prompt":"แผนภาพใช้เพื่ออะไร","choices":{"A":"แทนที่ชื่อเรื่องการนำเสนอ","B":"แสดงความสัมพันธ์ของส่วนต่าง ๆ หรือลำดับของกระบวนการ","C":"เก็บข้อมูลการขายดิบ"}},"chapter_key":"chapter-07","objective_key":"diagram_purpose"},{"en":{"prompt":"Where do you choose an animation for a selected object?","choices":{"A":"In the Animations tab, then set the effect.","B":"In the File menu under Save.","C":"In the Insert tab under Table."}},"id":"item_40","th":{"prompt":"จะเลือกแอนิเมชันให้กับวัตถุที่เลือกได้ที่ใด","choices":{"A":"ในแท็บแอนิเมชันแล้วกำหนดลูกเล่น","B":"ในเมนู File ใต้ Save","C":"ในแท็บแทรก ใต้ Table"}},"chapter_key":"chapter-08","objective_key":"animation_apply"},{"en":{"prompt":"How do you export slides as a handout PDF?","choices":{"A":"Insert > Pictures.","B":"View > Slide Sorter.","C":"File > Export > Create PDF, then choose the handout layout."}},"id":"item_41","th":{"prompt":"ส่งออกสไลด์เป็นไฟล์ PDF แบบเอกสารแจกอย่างไร","choices":{"A":"Insert > Pictures","B":"View > Slide Sorter","C":"File > Export > Create PDF แล้วเลือกรูปแบบเอกสารแจก"}},"chapter_key":"chapter-09","objective_key":"handout_export"},{"en":{"prompt":"Which principle helps the audience follow your message?","choices":{"A":"Use many fonts to look interesting.","B":"One slide, one main idea.","C":"Fill every slide with as much text as possible."}},"id":"item_42","th":{"prompt":"หลักการข้อใดช่วยผู้ฟังติดตามข้อความ","choices":{"A":"ใช้แบบอักษรหลายแบบเพื่อให้ดูน่าสนใจ","B":"หนึ่งสไลด์ หนึ่งความคิดหลัก","C":"เติมข้อความให้มากที่สุดในทุกสไลด์"}},"chapter_key":"chapter-01","objective_key":"principles"},{"en":{"prompt":"What should a storyboard sketch show?","choices":{"A":"Rough placement of text and visuals for each slide.","B":"Every final colour and shadow.","C":"Only the footnotes."}},"id":"item_43","th":{"prompt":"ร่างสตอรีบอร์ดควรแสดงอะไร","choices":{"A":"ตำแหน่งคร่าว ๆ ของข้อความและภาพในแต่ละสไลด์","B":"สีและเงาสุดท้ายทั้งหมด","C":"เพียงเชิงอรรถ"}},"chapter_key":"chapter-02","objective_key":"sb_visuals"},{"en":{"prompt":"What does the slide master control?","choices":{"A":"Only the text on the current slide.","B":"The speaker''s microphone volume.","C":"The shared fonts, colours, and layout of every slide."}},"id":"item_44","th":{"prompt":"สไลด์ต้นแบบควบคุมอะไร","choices":{"A":"เพียงข้อความบนสไลด์ปัจจุบัน","B":"ระดับเสียงไมโครโฟนของผู้บรรยาย","C":"แบบอักษร สี และเค้าโครงที่ใช้ร่วมกันในทุกสไลด์"}},"chapter_key":"chapter-03","objective_key":"slide_master"},{"en":{"prompt":"Why keep the slide order in the Slide Sorter?","choices":{"A":"It hides the speaker notes.","B":"It shows the flow of the story at a glance.","C":"It changes the font automatically."}},"id":"item_45","th":{"prompt":"ทำไมต้องคงลำดับสไลด์ใน Slide Sorter","choices":{"A":"ซ่อนบันทึกผู้บรรยาย","B":"เห็นลำดับของเรื่องในพริบตา","C":"เปลี่ยนแบบอักษรอัตโนมัติ"}},"chapter_key":"chapter-04","objective_key":"slide_order"},{"en":{"prompt":"Why add axis labels to a chart?","choices":{"A":"So the units and values are clear without guessing.","B":"So the chart uses more colours.","C":"So the file opens faster."}},"id":"item_46","th":{"prompt":"ทำไมต้องเพิ่มป้ายแกนให้แผนภูมิ","choices":{"A":"เพื่อให้หน่วยและค่าชัดเจนโดยไม่ต้องเดา","B":"เพื่อให้แผนภูมิใช้สีมากขึ้น","C":"เพื่อให้ไฟล์เปิดเร็วขึ้น"}},"chapter_key":"chapter-06","objective_key":"axis_labels"},{"en":{"prompt":"What does the Animation Pane show?","choices":{"A":"The list of fonts in the file.","B":"The notes for the presenter.","C":"The list and order of animations on the slide."}},"id":"item_47","th":{"prompt":"บานหน้าต่างแอนิเมชันแสดงอะไร","choices":{"A":"รายการของแบบอักษรในไฟล์","B":"บันทึกสำหรับผู้บรรยาย","C":"รายการและลำดับของแอนิเมชันบนสไลด์"}},"chapter_key":"chapter-08","objective_key":"animation_pane"},{"en":{"prompt":"What should you do before presenting to a customer?","choices":{"A":"Leave the room and let the customer read.","B":"Check the content, the equipment, and the time.","C":"Write the whole script on the slides."}},"id":"item_48","th":{"prompt":"ก่อนนำเสนอให้ลูกค้า ควรทำอะไร","choices":{"A":"ออกจากห้องและให้ลูกค้าอ่าน","B":"ตรวจสอบเนื้อหา อุปกรณ์ และเวลา","C":"เขียนบททั้งหมดบนสไลด์"}},"chapter_key":"chapter-01","objective_key":"preparation"},{"en":{"prompt":"Which storyboard works best for a sales proposal?","choices":{"A":"Problem, solution, evidence, and the next step.","B":"Ten slides of company history.","C":"One slide with only a logo."}},"id":"item_49","th":{"prompt":"สตอรีบอร์ดข้อใดเหมาะที่สุดสำหรับข้อเสนอการขาย","choices":{"A":"ปัญหา ทางแก้ หลักฐาน และขั้นตอนต่อไป","B":"สิบสไลด์เกี่ยวกับประวัติบริษัท","C":"หนึ่งสไลด์ที่มีเพียงโลโก้"}},"chapter_key":"chapter-02","objective_key":"sb_preparation"},{"en":{"prompt":"Why use a layout instead of placing every text box by hand?","choices":{"A":"It makes the text impossible to edit.","B":"It turns the slides into a PDF.","C":"It keeps positions consistent and saves time."}},"id":"item_50","th":{"prompt":"ทำไมควรใช้เค้าโครงสไลด์แทนการวางกล่องข้อความด้วยมือทีละกล่อง","choices":{"A":"ทำให้ข้อความแก้ไขไม่ได้","B":"เปลี่ยนสไลด์ให้เป็น PDF","C":"รักษาตำแหน่งสม่ำเสมอและประหยัดเวลา"}},"chapter_key":"chapter-03","objective_key":"layout"}]'::jsonb where version = '2026.11.1';
update public.ppg_posttest_instruments set items = '[{"en":{"prompt":"Which best describes a presentation?","choices":{"A":"Communicating one main idea the audience understands","B":"Using as much animation as possible","C":"Showing every piece of information you have"}},"id":"item_1","th":{"prompt":"ข้อใดอธิบายการนำเสนอได้ดีที่สุด","choices":{"A":"การสื่อสารความคิดหลักหนึ่งเรื่องให้ผู้ฟังเข้าใจ","B":"ใช้แอนิเมชันให้มาก","C":"แสดงข้อมูลทั้งหมดที่มี"}},"chapter_key":"chapter-01","objective_key":"definition"},{"en":{"prompt":"Which correctly describes a storyboard?","choices":{"A":"A slide that is already finished","B":"A slide-by-slide plan that drafts the message and visuals before you build","C":"A video file for presenting"}},"id":"item_2","th":{"prompt":"ข้อใดอธิบายสตอรีบอร์ดได้ถูกต้อง","choices":{"A":"สไลด์ที่สร้างเสร็จแล้ว","B":"แผนลำดับสไลด์ที่ร่างสาระและภาพก่อนลงมือ","C":"ไฟล์วิดีโอสำหรับนำเสนอ"}},"chapter_key":"chapter-02","objective_key":"sb_definition"},{"en":{"prompt":"Which program is used to create a presentation?","choices":{"A":"A spreadsheet program","B":"A video editor","C":"PowerPoint"}},"id":"item_3","th":{"prompt":"โปรแกรมใดใช้สร้างงานนำเสนอ","choices":{"A":"โปรแกรมตาราง","B":"โปรแกรมตัดต่อวิดีโอ","C":"PowerPoint"}},"chapter_key":"chapter-03","objective_key":"program_types"},{"en":{"prompt":"Which is the way to add a text box?","choices":{"A":"Go to the Insert tab and choose Text Box","B":"Go to the Home tab and click Bold","C":"Go to Slide Show"}},"id":"item_4","th":{"prompt":"ข้อใดเป็นวิธีเพิ่มกล่องข้อความ","choices":{"A":"ไปที่แท็บ Insert จากนั้นเลือก Text Box","B":"ไปที่แท็บ Home จากนั้นคลิก Bold","C":"ไปที่ Slide Show"}},"chapter_key":"chapter-04","objective_key":"text_boxes"},{"en":{"prompt":"Which picture source does not need an internet connection?","choices":{"A":"An online search","B":"A picture file on your computer","C":"Online Pictures"}},"id":"item_5","th":{"prompt":"ภาพจากแหล่งใดไม่ต้องใช้อินเทอร์เน็ต","choices":{"A":"ค้นหาออนไลน์","B":"ไฟล์ภาพในคอมพิวเตอร์","C":"ภาพออนไลน์"}},"chapter_key":"chapter-05","objective_key":"picture_sources"},{"en":{"prompt":"Which message suits a line chart?","choices":{"A":"The company address","B":"The team roster","C":"How sales changed over six months"}},"id":"item_6","th":{"prompt":"ข้อความใดเหมาะสมสำหรับแผนภูมิเส้น","choices":{"A":"ที่อยู่ของบริษัท","B":"รายชื่อของทีม","C":"ยอดขายเปลี่ยนไปอย่างไรในหกเดือน"}},"chapter_key":"chapter-06","objective_key":"chart_purpose"},{"en":{"prompt":"What makes a table easy to read?","choices":{"A":"A clear header row and balanced borders","B":"Colour in every cell","C":"A smaller font"}},"id":"item_7","th":{"prompt":"อะไรทำให้ตารางอ่านง่าย","choices":{"A":"หัวตารางชัดเจนและเส้นขอบเหมาะสม","B":"ใส่สีทุกเซลล์","C":"แบบอักษรเล็กลง"}},"chapter_key":"chapter-07","objective_key":"table_use"},{"en":{"prompt":"What is the result of a good slide transition?","choices":{"A":"The file gets bigger","B":"The audience follows the story smoothly","C":"The audience cannot read the slide in time"}},"id":"item_8","th":{"prompt":"ผลของการเปลี่ยนสไลด์ที่ดีคืออะไร","choices":{"A":"ไฟล์ใหญ่ขึ้น","B":"ผู้ฟังติดตามเรื่องได้อย่างต่อเนื่อง","C":"ผู้ฟังอ่านสไลด์ไม่ทัน"}},"chapter_key":"chapter-08","objective_key":"transition_purpose"},{"en":{"prompt":"What helps keep the audience with you?","choices":{"A":"Reading every word fast","B":"Avoiding eye contact","C":"Pausing at the main points and watching the pace"}},"id":"item_9","th":{"prompt":"อะไรช่วยให้ผู้ฟังติดตามคุณตลอดเวลา","choices":{"A":"อ่านทุกคำอย่างรวดเร็ว","B":"หลบสายตาผู้ฟัง","C":"หยุดที่ประเด็นหลักและสังเกตจังหวะการพูด"}},"chapter_key":"chapter-09","objective_key":"delivery_skills"},{"en":{"prompt":"What should a good storyboard frame contain?","choices":{"A":"The main message, a visual, and a speaker note","B":"Only a title","C":"Only an animation"}},"id":"item_10","th":{"prompt":"กรอบสตอรีบอร์ดที่ดีควรมีอะไร","choices":{"A":"สาระหลัก ภาพประกอบ และบันทึกผู้บรรยาย","B":"เฉพาะชื่อเรื่อง","C":"เฉพาะแอนิเมชัน"}},"chapter_key":"chapter-02","objective_key":"sb_components"},{"en":{"prompt":"Which is NOT a presentation program?","choices":{"A":"LibreOffice Impress","B":"A spreadsheet program","C":"Keynote"}},"id":"item_11","th":{"prompt":"ข้อใดไม่ใช่โปรแกรมนำเสนอ","choices":{"A":"LibreOffice Impress","B":"โปรแกรมตาราง","C":"Keynote"}},"chapter_key":"chapter-03","objective_key":"program_equivalents"},{"en":{"prompt":"Which list should use bullets?","choices":{"A":"Steps one to three","B":"A calculation formula","C":"A list of product features"}},"id":"item_12","th":{"prompt":"ข้อใดควรใช้สัญลักษณ์แสดงหัวข้อ","choices":{"A":"ขั้นตอนที่หนึ่งถึงสาม","B":"สูตรคำนวณ","C":"รายการคุณสมบัติสินค้า"}},"chapter_key":"chapter-04","objective_key":"bullets"},{"en":{"prompt":"To insert an online picture, which path do you use?","choices":{"A":"Insert, Pictures, Online Pictures","B":"Home, New Slide","C":"View, Slide Master"}},"id":"item_13","th":{"prompt":"การแทรกภาพออนไลน์ใช้เส้นทางใด","choices":{"A":"Insert จากนั้น Pictures จากนั้น Online Pictures","B":"Home จากนั้น New Slide","C":"View จากนั้น Slide Master"}},"chapter_key":"chapter-05","objective_key":"insert_path"},{"en":{"prompt":"Which chart is best for comparing the sales of five products in one month?","choices":{"A":"A line chart","B":"A column chart","C":"A pie chart"}},"id":"item_14","th":{"prompt":"แผนภูมิใดเหมาะที่สุดสำหรับเปรียบเทียบยอดขายของสินค้าห้ารายการในหนึ่งเดือน","choices":{"A":"แผนภูมิเส้น","B":"แผนภูมิคอลัมน์","C":"แผนภูมิวงกลม"}},"chapter_key":"chapter-06","objective_key":"chart_types"},{"en":{"prompt":"Before you insert a table, what must you set?","choices":{"A":"The slide background colour","B":"The narration sound","C":"The number of rows and columns"}},"id":"item_15","th":{"prompt":"ก่อนแทรกตารางต้องตั้งอะไร","choices":{"A":"สีพื้นหลังสไลด์","B":"เสียงบรรยาย","C":"จำนวนแถวและคอลัมน์"}},"chapter_key":"chapter-07","objective_key":"table_create"},{"en":{"prompt":"After choosing the Transitions tab, what do you choose?","choices":{"A":"A transition from the gallery","B":"The font","C":"The number of columns"}},"id":"item_16","th":{"prompt":"หลังเลือกแท็บ Transitions ต้องเลือกอะไร","choices":{"A":"การเปลี่ยนสไลด์จากแกลเลอรี","B":"แบบอักษร","C":"จำนวนคอลัมน์"}},"chapter_key":"chapter-08","objective_key":"transition_apply"},{"en":{"prompt":"Before the audience joins the meeting, what should you open?","choices":{"A":"A new password","B":"The file and Presenter View","C":"The product price"}},"id":"item_17","th":{"prompt":"ก่อนผู้ฟังเข้าร่วมประชุมควรเปิดอะไร","choices":{"A":"รหัสผ่านใหม่","B":"ไฟล์และมุมมองผู้นำเสนอ","C":"ราคาของสินค้า"}},"chapter_key":"chapter-09","objective_key":"delivery_setup"},{"en":{"prompt":"What is the goal of a training presentation?","choices":{"A":"For the audience to remember the company name","B":"For the audience to buy immediately only","C":"For the audience to apply the knowledge"}},"id":"item_18","th":{"prompt":"การนำเสนอเพื่อฝึกอบรมมีเป้าหมายใด","choices":{"A":"ให้ผู้ฟังจำชื่อบริษัท","B":"ให้ผู้ฟังซื้อทันทีเท่านั้น","C":"ให้ผู้ฟังนำความรู้ไปปฏิบัติ"}},"chapter_key":"chapter-01","objective_key":"purposes"},{"en":{"prompt":"On which tab do you add a new slide?","choices":{"A":"Home","B":"View","C":"Slide Show"}},"id":"item_19","th":{"prompt":"เพิ่ม New Slide ที่แท็บใด","choices":{"A":"Home","B":"View","C":"Slide Show"}},"chapter_key":"chapter-03","objective_key":"create_presentation"},{"en":{"prompt":"Which is centre alignment?","choices":{"A":"Increasing the line spacing","B":"Placing text in the centre of the slide","C":"Placing text against the left margin"}},"id":"item_20","th":{"prompt":"ข้อใดคือการจัดกึ่งกลาง","choices":{"A":"เพิ่มระยะห่างบรรทัด","B":"วางข้อความให้อยู่กึ่งกลางสไลด์","C":"วางข้อความชิดขอบซ้าย"}},"chapter_key":"chapter-04","objective_key":"alignment"},{"en":{"prompt":"Which feature puts a picture inside a shape frame?","choices":{"A":"Bold","B":"Hide Slide","C":"Crop to Shape"}},"id":"item_21","th":{"prompt":